def run_length(text):
    if not text:
        return []
    result = []
    count = 1
    for i in range(1, len(text)):
        if text[i] == text[i - 1]:
            count += 1
        else:
            result.append([text[i - 1], count])
            count = 1
    result.append([text[-1], count])
    return result

def run_length(s: str) -> list:
    if not s:
        return []
    result = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result

def run_length(s: str) -> list[list[str, int]]:
    if not s:
        return []
    result: list[list[str, int]] = []
    count = 1
    prev = s[0]
    for char in s[1:]:
        if char == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = char
            count = 1
    result.append([prev, count])
    return result
